    useEffect(() => () => urls.current.forEach((u) => URL.revokeObjectURL(u)), []);
    const update = useCallback((id: string, fn: (item: UploadItem) => UploadItem) => {
        setItems((list) => list.map((item) => (item.id === id ? fn(item) : item)));
    }, []);
    const onTick = useCallback((id: string) => {
        update(id, (item) => {
            if (item.status !== "uploading")
                return item;
            const next = tickItem(item);
            if (next.status === "complete")
                setAnnounce(`${item.name} uploaded`);
            if (next.status === "failed")
                setAnnounce(`${item.name} failed: Connection dropped`);
            return next;
        });
    }, [update]);
    useEffect(() => {
        const available = Math.max(0, 3 - items.filter((item) => item.status === "uploading").length);
        if (available && items.some((item) => item.status === "waiting")) {
            const starting = new Map<string, UploadItem>();
            for (const item of items.filter((entry) => entry.status === "waiting").slice(0, available)) {
                let failOnce = item.failOnce;
                if (!startedItems.current.has(item.id)) {
                    startedItems.current.add(item.id);
                    const fileKey = `${item.name}\0${item.size}`;
                    const firstStart = !startedFiles.current.has(fileKey);
                    startedFiles.current.add(fileKey);
                    failOnce = firstStart && startedFiles.current.size === 2;
                }
                starting.set(item.id, { ...item, status: "uploading", failOnce });
            }
            setItems((list) => list.map((item) => starting.get(item.id) ?? item));
        }
    }, [items]);
    const actions: RowActions = {
        onTick,
        onPause: (id) => update(id, (item) => ({ ...item, status: "paused", speed: null })),
