          <motion.div className="art:mt-8 art:rounded-3xl art:border art:border-border art:bg-background art:p-2 art:@min-[640px]/artemis:p-3" initial={REVEAL_INITIAL} animate={REVEAL_SHOWN} transition={reduce ? { duration: 0 } : { duration: 0.5, ease: ARTEMIS_EASE_OUT, delay: 0.07 }}>
            <motion.div ref={dropzoneRef} role="button" tabIndex={0} aria-label="Upload files. Press Enter to choose files." aria-describedby={`${artemisInstanceId}-R_d6pbsnpfdb_`} className={`art:group art:relative art:flex art:cursor-pointer art:flex-col art:items-center art:rounded-3xl art:border art:border-dashed art:px-6 art:pt-9 art:pb-7 art:text-center art:outline-none art:transition-colors art:duration-200 art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background ${dragging ? "art:border-foreground/50 art:bg-foreground/[0.03]" : "art:border-border art:hover:border-foreground/30"}`} initial={false} animate={{ scale: !reduce && dragging ? 1.015 : 1 }} transition={reduce ? { duration: 0 } : ARTEMIS_SPRING_PANEL} onClick={choose} onKeyDown={(e) => {
            if (e.key === "Enter" || e.key === " ") {
                e.preventDefault();
