        }} onDragEnter={onDragEnter} onDragOver={onDragOver} onDragLeave={onDragLeave} onDrop={onDrop}>
              <input ref={inputRef} type="file" accept="image/*,.pdf,.doc,.docx,.txt,.md,.csv,.xls,.xlsx,.zip" multiple tabIndex={-1} aria-hidden="true" className="art:sr-only" onClick={(e) => e.stopPropagation()} onChange={(e) => {
            addFiles(Array.from(e.currentTarget.files ?? []));
