        }}/>
              <motion.svg viewBox="-14 -14 116 96" className="art:h-24 art:w-28 art:overflow-visible" aria-hidden="true" animate={!reduce && dropzoneInView ? { y: [-3, 3] } : { y: 0 }} transition={reduce ? { duration: 0 } : dropzoneInView ? { duration: 3.6, ease: "easeInOut", repeat: Infinity, repeatType: "mirror" } : { duration: 0.4, ease: "linear" }}>
                <motion.g style={{ transformBox: "fill-box", transformOrigin: "50% 50%" }} initial={false} animate={dragging ? { x: -24, y: -2, rotate: -20 } : { x: -7, y: 2, rotate: -7 }} transition={reduce ? { duration: 0 } : FAN}>
