                <motion.g style={{ transformBox: "fill-box", transformOrigin: "50% 50%" }} initial={false} animate={dragging ? { y: -8, scale: 1.05 } : { y: 0, scale: 1 }} transition={reduce ? { duration: 0 } : FAN}>
                  <g transform="translate(18 10)">
