              <motion.div className="art:fixed art:inset-0 art:bg-foreground/10 art:backdrop-blur-xl" aria-hidden="true" initial={reduce ? false : { opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0, transition: reduce ? { duration: 0 } : { duration: 0.15, ease: ARTEMIS_EASE_OUT } }} transition={reduce ? { duration: 0 } : { duration: 0.2, ease: ARTEMIS_EASE_OUT }}/>
