                        <Description className="art:font-mono art:text-muted-foreground art:text-xs art:tabular-nums">{`${formatBytes(shown.size)} \u00B7 ${shown.mime}`}</Description>
                      </div>
                      <button type="button" onClick={() => setPreviewId(null)} className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:text-muted-foreground art:hover:bg-primary/5 art:hover:text-foreground art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:size-9 art:rounded-full" aria-label="Close preview">
