                          <path d="m6 6 12 12"/>
                        </svg>
                      </button>
                    </div>
                  </DialogPanel>
                </div>
              </div>
            </Dialog>)}
        </AnimatePresence>
        <output aria-live="polite" className="art:sr-only">{announce}</output>
      </section>
    </>);
}

