          <motion.path d="M6 10.4l2.6 2.6L14 7.5" className="art:fill-none art:stroke-emerald-600 art:dark:stroke-emerald-400" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" initial={reduce ? false : { pathLength: 0 }} animate={{ pathLength: 1 }} transition={reduce ? { duration: 0 } : { duration: 0.35, delay: 0.12, ease: ARTEMIS_EASE_OUT }}/>
